package avatar

props {
  Src      gx.URL
  Alt      string   = ""
  Fallback string   = ""
  Size     Size     = Md
  Class    string   = ""
  Attrs    gx.Attrs = nil
}

<span class={gx.Cx("relative flex shrink-0 overflow-hidden rounded-full", p.sizeClass(), p.Class)} {...p.Attrs}>
  if p.Src != "" {
    <img src={p.Src} alt={p.Alt} class="aspect-square size-full object-cover" />
  } else if p.Fallback != "" {
    <span class="flex size-full items-center justify-center rounded-full bg-muted text-xs font-medium text-muted-foreground">{p.Fallback}</span>
  }
</span>

package avatar

import "github.com/alternayte/gx"

// Size is the diameter of an avatar.
type Size string

// The sizes of avatar.Avatar.
const (
	Sm Size = "sm"
	Md Size = "md"
	Lg Size = "lg"
)

var sizeClass = gx.Enum[Size]{
	Sm: "size-6 text-xs",
	Md: "size-8",
	Lg: "size-10 text-base",
}

// sizeClass returns the classes of one avatar size; a zero value is Md.
func (p AvatarProps) sizeClass() string {
	if p.Size == "" {
		return sizeClass[Md]
	}
	return sizeClass[p.Size]
}
